-- ATM finder: ATMs, deposit machines (CRM) and branches of ABA, ACLEDA, Canadia, Wing and Sathapana from
-- OpenStreetMap (© OpenStreetMap contributors, ODbL). Public data: anyone may read it; only the bot's weekly
-- refresh (bot_atm_sync) writes it. Distances are computed by the app (src/lib/atm.ts).

create table if not exists public.bank_atms (
  osm_ref text primary key,
  bank_code text not null check (bank_code in ('ABA', 'ACLEDA', 'CANADIA', 'WING', 'SATHAPANA')),
  type text not null check (type in ('ATM', 'CRM', 'BRANCH')),
  name_kh text,
  name_en text,
  address text,
  province text,
  province_km text,
  latitude double precision not null,
  longitude double precision not null,
  currencies text[],
  is_24h boolean not null default true,
  source text not null default 'osm',
  updated_at timestamptz not null default now()
);
create index if not exists bank_atms_bank_idx on public.bank_atms (bank_code, type);
alter table public.bank_atms enable row level security;
revoke all on public.bank_atms from anon, authenticated;
grant select on public.bank_atms to anon, authenticated;
drop policy if exists bank_atms_read on public.bank_atms;
create policy bank_atms_read on public.bank_atms for select to anon, authenticated using (true);

-- The weekly refresh: upsert what OpenStreetMap lists now and drop what it no longer lists. A short answer
-- (under 200 rows — Overpass cut off or failed) changes nothing.
create or replace function public.bot_atm_sync(p_key text, p_rows jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  n int := jsonb_array_length(coalesce(p_rows, '[]'::jsonb));
  removed int;
begin
  perform public.require_bot(p_key);
  if n < 200 then
    return jsonb_build_object('status', 'skipped', 'rows', n);
  end if;
  select r.osm_ref, r.bank_code, r.type, r.name_kh, r.name_en, r.address, r.province, r.province_km, r.latitude, r.longitude, r.currencies, r.is_24h, now()
  from jsonb_to_recordset(p_rows) as r(osm_ref text, bank_code text, type text, name_kh text, name_en text, address text, province text, province_km text,
    latitude double precision, longitude double precision, currencies text[], is_24h boolean)
  on conflict (osm_ref) do update set bank_code = excluded.bank_code, type = excluded.type, name_kh = excluded.name_kh, name_en = excluded.name_en,
    address = excluded.address, province = excluded.province, province_km = excluded.province_km, latitude = excluded.latitude,
    longitude = excluded.longitude, currencies = excluded.currencies, is_24h = excluded.is_24h, updated_at = now();
  delete from public.bank_atms a
  where a.source = 'osm' and not exists (select 1 from jsonb_array_elements(p_rows) x where x->>'osm_ref' = a.osm_ref);
  get diagnostics removed = row_count;
  return jsonb_build_object('status', 'ok', 'rows', n, 'removed', removed);
end;
$$;
revoke all on function public.bot_atm_sync(text, jsonb) from public;
grant execute on function public.bot_atm_sync(text, jsonb) to anon, authenticated;

-- Seed: 394 ATMs and branches of ABA, ACLEDA, Canadia, Wing and Sathapana — © OpenStreetMap contributors (ODbL).
on conflict (osm_ref) do nothing;
